  if (typeof icon === 'function') {
    IconComponent = icon
  } else if (typeof icon === 'string') {
    // Map string names to icon components if needed
    const iconMap: Record<string, LucideIcon> = {
      'users': Users,
      'calendar': Calendar,
      'clipboard': ClipboardList
    }
    IconComponent = iconMap[icon.toLowerCase()] || Users
