  SELECT id INTO v_thread_id
  FROM public.message_threads
  WHERE application_id = p_application_id;

  -- Create new thread if it doesn't exist
  IF v_thread_id IS NULL THEN
    INSERT INTO public.message_threads (
      application_id,
      listing_id,
      coach_id,
