import { requireRole } from "@/lib/auth/utils"
import { createServerSupabaseClient } from "@/lib/supabase/server"
import { MessageThreads } from "./message-threads"
import { MessageSquare } from "lucide-react"

export default async function CoachMessagesPage() {
  const user = await requireRole('coach')
  const supabase = await createServerSupabaseClient()

  // Fetch message threads with latest message
  const { data: threads } = await supabase
    .from('message_threads')
    .select(`
      *,
      org:org_id(email),
      listing:listings!inner(
        title,
        org:users!listings_org_id_fkey(
          org_profiles!inner(org_name)
        )
      ),
      application:applications!inner(
        status
      ),
      messages(
        content,
        sender_id,
        created_at,
        is_read
      )
    `)
    .eq('coach_id', user.id)
    .order('last_message_at', { ascending: false, nullsFirst: false })

  // Get unread counts
  const { data: notifications } = await supabase
    .from('message_notifications')
    .select('thread_id, unread_count')
    .eq('user_id', user.id)
    .gt('unread_count', 0)

  const unreadCounts = notifications?.reduce((acc, n) => {
    acc[n.thread_id] = n.unread_count
    return acc
  }, {} as Record<string, number>) || {}

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <MessageSquare className="w-6 h-6" />
          <h1 className="text-3xl font-bold">Messages</h1>
        </div>
        <p className="text-muted-foreground">
          Communicate with organizations about opportunities
        </p>
      </div>

      <MessageThreads 
        threads={threads || []} 
        currentUserId={user.id}
        unreadCounts={unreadCounts}
        isCoach={true}
      />
    </div>
  )
}

"use client"

import { useState, useEffect, use } from "react"
import { useRouter } from "next/navigation"
import { createClient } from "@/lib/supabase/client"
import { GlassCard } from "@/components/ui/glass-card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { BadgeRow } from "@/components/ui/badge-row"
import { Tooltip, TooltipTrigger, TooltipContent } from "@/components/ui/tooltip"
import Link from "next/link"
import { 
  MapPin, 
  Calendar, 
  Clock, 
  DollarSign,
  Building2,
  ArrowLeft,
  Send,
  AlertCircle,
  CheckCircle
} from "lucide-react"
import { format } from "date-fns"

interface PageProps {
  params: Promise<{
    id: string
  }>
}

export default function CoachListingDetailPage({ params }: PageProps) {
  const resolvedParams = use(params)
  const router = useRouter()
  const [listing, setListing] = useState<any>(null)
  const [loading, setLoading] = useState(true)
  const [applying, setApplying] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)
  const [hasApplied, setHasApplied] = useState(false)
  const [applicationMessage, setApplicationMessage] = useState("")
  const [proposedRate, setProposedRate] = useState("")
  const [isVerified, setIsVerified] = useState(false)

  const supabase = createClient()

  useEffect(() => {
    loadListing()
  }, [resolvedParams.id])

  async function loadListing() {
    try {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) {
        router.push('/auth/sign-in')
        return
      }

      // Check if coach is verified
      const { data: profile } = await supabase
        .from('coach_profiles')
        .select('wwcc_number, insurance_url, first_aid_url')
        .eq('user_id', user.id)
        .single()

      setIsVerified(!!(profile?.wwcc_number && profile?.insurance_url && profile?.first_aid_url))

      // Get listing details
      const { data: listingData, error: listingError } = await supabase
        .from('listings')
        .select(`
          *,
          org:users!listings_org_id_fkey(
            org_profiles!inner(
              org_name,
              org_type
            )
          )
        `)
        .eq('id', resolvedParams.id)
        .single()

      if (listingError) {
        setError('Listing not found')
        return
      }

      setListing(listingData)

      // Check if already applied
      const { data: existingApplication } = await supabase
        .from('applications')
        .select('id')
        .eq('listing_id', resolvedParams.id)
        .eq('coach_id', user.id)
        .single()

      setHasApplied(!!existingApplication)

    setHasApplied(!!existingApplication)
  } catch (err) {
    setError('Failed to load listing')
  } finally {
    setLoading(false)
  }
}

async function handleApply() {
  if (!applicationMessage.trim()) {
    setError("Please include a message with your application")
    return
  }

  setApplying(true)
  setError(null)

  try {
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) {
      setError('You must be logged in to apply')
      return
    }

    const { error: applyError } = await supabase
      .from('applications')
      .insert({
        listing_id: resolvedParams.id,
        coach_id: user.id,
        message: applicationMessage,
        proposed_rate: proposedRate ? parseFloat(proposedRate) : null,
        status: 'pending'
      })

    if (applyError) {
      setError(applyError.message)
      return
    }

    setSuccess(true)
    setHasApplied(true)
    setTimeout(() => {
      router.push('/coach/applications')
    }, 2000)
  } catch (err) {
    setError('Failed to submit application')
  } finally {
    setApplying(false)
  }
}

if (loading) {
  return (
    <div className="container mx-auto px-4 py-8">
      <div className="animate-pulse">
        <div className="h-8 bg-muted rounded w-1/3 mb-4"></div>
        <div className="h-64 bg-muted rounded"></div>
      </div>
    </div>
  )
}

if (!listing) {
  return (
    <div className="container mx-auto px-4 py-8">
      <GlassCard className="p-8 text-center">
        <AlertCircle className="w-12 h-12 mx-auto mb-4 text-destructive" />
        <h1 className="text-xl font-semibold mb-2">Listing Not Found</h1>
        <p className="text-muted-foreground mb-4">
          This listing may have been removed or is no longer available
        </p>
        <Button asChild>
          <Link href="/coach/listings">
            Browse Other Opportunities
          </Link>
        </Button>
      </GlassCard>
    </div>
  )
}

const requiredBadgesList = listing.required_badges?.map((badge: string) => ({
  label: badge.toUpperCase().replace('-', ' '),
  status: 'verified' as const
})) || []

return (
  <div className="container mx-auto px-4 py-8 max-w-4xl">
    {/* Header */}
    <div className="mb-8">
      <Link 
        href="/coach/listings" 
        className="inline-flex items-center text-sm text-muted-foreground hover:text-foreground mb-4"
      >
        <ArrowLeft className="w-4 h-4 mr-2" />
        Back to listings
      </Link>

      <div className="flex items-start justify-between">
        <div>

"use client"

import { Button } from "@/components/ui/button"
import { LogOut } from "lucide-react"
import { createClient } from "@/lib/supabase/client"
import { useRouter } from "next/navigation"

interface SignOutButtonProps {
  className?: string
}

export function SignOutButton({ className }: SignOutButtonProps) {
  const router = useRouter()
  const supabase = createClient()

  const handleSignOut = async () => {
    await supabase.auth.signOut()
    router.push('/')
    router.refresh()
  }

  return (
    <Button 
      onClick={handleSignOut}
      variant="ghost" 
      className={className}
    >
      <LogOut className="w-4 h-4" />
      Sign Out
    </Button>
  )
}

